SELECT \"nct\", \"author\", \"year\", \"pubmed_id\", \"follow_up_duration_for_primary_endpoint_s_in_months_overall\" AS median_follow_up_overall, \"follow_up_duration_for_primary_endpoint_s_in_months_rx\" AS median_follow_up_rx, \"follow_up_duration_for_primary_endpoint_s_in_months_control\" AS median_follow_up_control FROM public.\"clinical_trials\" WHERE \"cancer_type\" ILIKE '%esophageal%' OR \"cancer_type\" ILIKE '%gej%';